           if (key === "text") {
             element.textContent = value;
             return;
           }

           if (key === "htmlFor") {
             element.htmlFor = value;
             return;
           }

           if (key === "attributes") {
             Object.entries(value).forEach(([attribute, attributeValue]) => {
               if (attributeValue === true) {
                 element.setAttribute(attribute, "");
               } else if (attributeValue !== false && attributeValue != null) {
                 element.setAttribute(attribute, attributeValue);
               }
             });
             return;
           }

           element[key] = value;
         });

         children.flat().forEach((child) => {
           if (child == null) {
             return;
           }

           element.append(child.nodeType ? child : document.createTextNode(child));
         });

         return element;
       };

       const FormField = ({ id, label, type, placeholder, required = false, helperText, autoComplete, inputMode }) =>
         h("div", { className: "form-field" }, [
           h("label", { htmlFor: id }, [
             label,
             required ? h("span", { className: "required-indicator", text: " *" }) : null,
           ]),
           h("input", {
             id,
             name: id,
             type,
             placeholder,
             required,
             autoComplete,
             inputMode,
             attributes: {
               "aria-describedby": helperText ? `${id}-helper` : null,
             },
           }),
           helperText
             ? h("p", {
                 className: "helper-text",
                 id: `${id}-helper`,
                 text: helperText,
               })
             : null,
         ]);

       const ContactForm = () =>
         h("section", { className: "support-card" }, [
           h("h2", { className: "card-title", text: "Send a support request" }),
           h("p", {
             className: "card-copy",
             text: "Tell us how to reach you and our team will follow up with the right next step.",
           }),
           h(
             "form",
             {
               attributes: {
                 action: "#",
                 method: "post",
               },
             },
             [
               FormField({
                 id: "fullName",
                 label: "Full name",
                 type: "text",
                 placeholder: "Jordan Lee",
                 required: true,
                 autoComplete: "name",
               }),
               FormField({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 placeholder: "jordan@example.com",
                 required: true,
                 autoComplete: "email",
               }),
               FormField({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 placeholder: "(555) 123-4567",
                 autoComplete: "tel",
                 inputMode: "tel",
                 helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
               }),
               h("button", {
                 className: "submit-button",
                 type: "submit",
                 text: "Submit request",
               }),
             ]
           ),
         ]);

       const SupportInfo = () =>
         h("section", { className: "support-copy" }, [
           h("div", {}, [
             h("div", { className: "eyebrow", text: "Support page" }),
             h("h1", { text: "Get help from our product specialists." }),
             h("p", {
               className: "lead",
               text: "Share a few contact details and a member of the support team will reach out with guidance tailored to your issue.",
             }),
           ]),
           h("ul", { className: "support-points" }, [
             h("li", {}, [
               h("strong", { text: "Fast triage" }),
               "We review incoming requests quickly so the right team can respond.",
             ]),
             h("li", {}, [
               h("strong", { text: "Clear handoff" }),
               "Your contact details stay organized for follow-up across email or phone.",
             ]),
           ]),
         ]);

       const App = () =>
         h("main", { className: "page-shell" }, [
           h("div", { className: "support-layout" }, [SupportInfo(), ContactForm()]),
         ]);

       document.getElementById("root").append(App());
     </script>
   </body>
 </html>

